      font-weight: 800;
      font-size: 14px;
    }

    .nav-main {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-item {
      position: relative;
    }

    .nav-link {
      color: var(--primary-dark);
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      padding: 8px 0;
      display: flex;
      align-items: center;
      gap: 4px;
      cursor: pointer;
      background: none;
      border: none;
    }

    .nav-link:hover {
      color: var(--accent-blue);
    }

    .nav-link svg {
      width: 16px;
      height: 16px;
      transition: transform 0.2s;
    }

    .nav-item:hover .nav-link svg {
