      grid-template-columns: repeat(3, 1fr);
    }

    /* Main Content */
    .main {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Category Filters */
    .filters-section {
      padding: 32px 0 24px;
    }

    .filters-row {
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    .search-wrapper {
      position: relative;
      margin-left: auto;
    }

    .search-input {
      width: 240px;
      padding: 10px 16px;
      padding-left: 40px;
      border: 1px solid var(--border-color);
      border-radius: var(--radius-full);
      font-size: 14px;
      background: var(--bg-white);
      transition: all 0.2s;
    }

    .search-input:focus {
      outline: none;
      border-color: var(--accent-blue);
      box-shadow: 0 0 0 3px rgba(0, 114, 245, 0.1);
    }

    .search-icon {
      position: absolute;
      left: 14px;
      top: 50%;
      transform: translateY(-50%);
      width: 18px;
      height: 18px;
      color: var(--text-secondary);
    }

    .category-pills {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
    }

    .pill {
      padding: 8px 16px;
      border-radius: var(--radius-full);
      font-size: 13px;
      font-weight: 500;
      border: 1px solid var(--border-color);
      background: var(--bg-white);
      color: var(--primary-dark);
      cursor: pointer;
      transition: all 0.2s;
    }

    .pill:hover {
      border-color: var(--accent-blue);
      color: var(--accent-blue);
    }

    .pill.active {
      background: var(--primary-dark);
      color: white;
      border-color: var(--primary-dark);
    }

    /* Featured Articles */
    .featured-section {
      padding-bottom: 48px;
