    .featured-card-content {
      padding: 24px;
    }

    .featured-card:first-child .featured-card-content {
      padding: 32px;
    }

    .card-meta {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 12px;
    }

    .card-date {
      font-size: 13px;
      color: var(--text-secondary);
    }

    .card-author {
      font-size: 13px;
      color: var(--primary-dark);
      font-weight: 500;
    }

    .card-title {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 12px;
      line-height: 1.3;
    }

    .featured-card:first-child .card-title {
      font-size: 28px;
    }

    .card-excerpt {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    /* Stats Bar */
    .stats-bar {
      background: var(--primary-dark);
      border-radius: var(--radius-lg);
      padding: 24px 32px;
      margin-bottom: 24px;
