      border: 1px solid var(--border-color);
      overflow: hidden;
      transition: all 0.3s;
      cursor: pointer;
    }

    .news-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .news-card-image {
      height: 160px;
      background: linear-gradient(135deg, #f0f0f0 0%, #e0e0e0 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
    }

    .news-card-content {
      padding: 20px;
    }

    .news-card .card-meta {
      margin-bottom: 8px;
    }

    .news-card .card-title {
      font-size: 16px;
      margin-bottom: 8px;
    }

    .news-card .card-excerpt {
      font-size: 13px;
      -webkit-line-clamp: 2;
    }

    .category-tag {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      padding: 4px 8px;
      border-radius: var(--radius-sm);
      background: rgba(0, 114, 245, 0.1);
      color: var(--accent-blue);
    }

    .no-results {
      text-align: center;
      padding: 64px 24px;
      display: none;
    }

    .no-results.show {
      display: block;
    }

    .no-results-icon {
      font-size: 48px;
      margin-bottom: 16px;
    }

    .no-results h3 {
      font-size: 18px;
      margin-bottom: 8px;
    }

    .no-results p {
      color: var(--text-secondary);
