      font-weight: 600;
      background: var(--bg-white);
      border: 1px solid var(--border-color);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: all 0.2s;
    }

    .btn-show-more:hover {
      background: var(--primary-dark);
      color: white;
      border-color: var(--primary-dark);
    }

    /* CTA Banner */
    .cta-section {
      background: var(--primary-dark);
      border-radius: var(--radius-lg);
      padding: 48px;
      margin-bottom: 48px;
