      grid-template-columns: 2fr 1fr;
      gap: 48px;
      align-items: center;
    }

    .cta-content h2 {
      font-size: 28px;
      font-weight: 700;
      color: white;
      margin-bottom: 12px;
    }

    .cta-content p {
      color: rgba(255,255,255,0.7);
      font-size: 16px;
    }

    .cta-buttons {
      display: flex;
      gap: 12px;
      margin-top: 24px;
    }

    .btn-cta-primary {
      background: var(--accent-blue);
      color: white;
      border: none;
      padding: 12px 24px;
      border-radius: var(--radius-md);
      font-weight: 600;
    }

    .btn-cta-secondary {
      background: transparent;
      color: white;
      border: 1px solid rgba(255,255,255,0.3);
      padding: 12px 24px;
      border-radius: var(--radius-md);
      font-weight: 500;
    }

    .cta-enterprise {
