    .cta-enterprise h3 {
      color: white;
      font-size: 16px;
      margin-bottom: 8px;
    }

    .cta-enterprise p {
      color: rgba(255,255,255,0.6);
      font-size: 13px;
      margin-bottom: 16px;
    }

    .btn-enterprise {
      background: transparent;
      color: white;
      border: 1px solid rgba(255,255,255,0.5);
      padding: 10px 20px;
      border-radius: var(--radius-md);
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.2s;
    }

    .btn-enterprise:hover {
      background: white;
      color: var(--primary-dark);
