    /* Footer */
    .footer {
      background: var(--bg-white);
      border-top: 1px solid var(--border-color);
      padding: 48px 0 24px;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 600;
      color: var(--primary-dark);
      margin-bottom: 16px;
    }

    .footer-col ul {
      list-style: none;
    }

    .footer-col li {
      margin-bottom: 8px;
    }

    .footer-col a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 13px;
    }

    .footer-col a:hover {
      color: var(--accent-blue);
    }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 24px;
      border-top: 1px solid var(--border-color);
    }

    .footer-legal {
      display: flex;
      gap: 24px;
    }

    .footer-legal a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 13px;
    }

    .footer-legal a:hover {
      color: var(--primary-dark);
    }

    .footer-status {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      color: var(--text-secondary);
    }

    .status-dot {
      width: 8px;
      height: 8px;
      background: #22c55e;
      border-radius: 50%;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .featured-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .featured-card:first-child {
        grid-column: span 2;
      }

      .latest-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-grid {
        grid-template-columns: repeat(3, 1fr);
      }

      .mega-menu {
        min-width: 500px;
      }
    }

    @media (max-width: 768px) {
      .header-inner {
        height: auto;
        padding: 12px 16px;
        flex-wrap: wrap;
        gap: 12px;
      }

      .nav-main {
        display: none;
      }

      .filters-row {
        flex-direction: column;
        align-items: stretch;
      }

      .search-wrapper {
        margin-left: 0;
      }

      .search-input {
        width: 100%;
      }

      .category-pills {
        justify-content: flex-start;
      }

      .featured-grid,
      .latest-grid {
        grid-template-columns: 1fr;
      }

      .featured-card:first-child {
        grid-column: span 1;
      }

      .stats-bar {
        flex-direction: column;
        text-align: center;
      }

      .cta-section {
        grid-template-columns: 1fr;
        padding: 32px 24px;
        text-align: center;
      }

      .cta-buttons {
        justify-content: center;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-bottom {
        flex-direction: column;
        gap: 16px;
        text-align: center;
      }
    }

    /* Author Avatar */
    .author-avatar {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--accent-blue) 0%, #005BB5 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 10px;
      font-weight: 600;
    }

    /* Hidden utility */
    .hidden {
      display: none !important;
    }
  </style>
</head>
